/* Server-priced Stripe Checkout. Returning from Stripe never grants credits. */
'use strict';
let paymentCatalog=null,paymentOrders=[],paymentCursor=null,paymentOlderLoaded=false,paymentLoading=false,paymentPoll=null,paymentReturnOrder=null,paymentReturnKind='',paymentSubmitting=false;
const paymentStatus={CREATING:'准备收银台',OPEN:'待支付',PROCESSING:'确认中',PAID:'已到账',EXPIRED:'已过期',FAILED:'支付失败',REVIEW:'待核对'};
const paymentRequestKeys=new Map();
function money(amount,currency){currency=currency.toUpperCase();const formatter=new Intl.NumberFormat('zh-CN',{style:'currency',currency});const digits=formatter.resolvedOptions().maximumFractionDigits;return `<span data-i18n-currency="${esc(currency)}" data-minor-amount="${Number(amount)}">${formatter.format(Number(amount)/10**digits)}</span>`;}
function paymentOrderHTML(order){const test=order.environment==='TEST',paid=order.status==='PAID',pending=['CREATING','OPEN'].includes(order.status),activeEnv=order.environment===paymentCatalog?.environment;return `<article class="payment-order" data-payment-id="${order.id}"><div><strong>${esc(order.name)}</strong><small>${esc(order.orderNo)} · ${new Date(order.created).toLocaleString('zh-CN')}</small>${order.error?`<p>${esc(order.error)}</p>`:''}</div><div><strong>${money(order.amountMinor,order.currency)}</strong><small>${points(order.creditPoints)} ${test?'测试入账积分':'积分'}</small></div><div><span class="task-status ${paid?'done':order.status==='FAILED'?'failed':''}">${test?'测试 · ':''}${paid&&test?'充值成功':esc(paymentStatus[order.status]||order.status)}</span>${pending&&activeEnv&&paymentCatalog?.enabled?`<button class="secondary-btn" data-action="payment-resume" data-id="${order.id}">继续支付</button>`:''}</div></article>`;}
function renderPayments(){
 const title=header('充值与订单','通过 Stripe 安全收银台购买创作积分。','<button class="secondary-btn" data-action="payments-refresh">刷新订单</button>');
 if(!cloudUser){$('#view').innerHTML=title+'<div class="empty"><h2>登录后查看充值套餐与订单</h2><button class="primary-btn" data-action="cloud-login">登录 / 注册</button></div>';return;}
 const catalog=paymentCatalog,test=catalog?.environment!=='LIVE';
 let banner='';if(paymentReturnKind==='cancel')banner='<div class="payment-notice">你已返回工作台。未支付的订单仍可在下方继续支付，是否到账以订单状态为准。</div>';
 else if(paymentReturnKind==='success')banner='<div class="payment-notice">正在核对 Stripe 支付结果。付款跳转本身不会增加积分，确认到账后订单会自动更新。</div>';
 if(paymentReturnOrder){const returned=paymentOrders.find(o=>o.id===paymentReturnOrder);if(returned?.status==='PAID')banner=`<div class="payment-notice success">${returned.environment==='TEST'?'Stripe 测试支付已确认，测试入账已记录，真实可用积分保持不变。':'Stripe 支付已确认，积分已到账。'}</div>`;}
 $('#view').innerHTML=title+banner+`<div class="payment-mode"><span class="task-status">${test?'Stripe 测试模式':'Stripe 正式收款'}</span><span>${test?'测试套餐不产生真实扣款，测试入账积分不用于线上模型调用。':'价格与积分数量以当前套餐为准，付款确认后自动到账。'}</span></div>${catalog&&!catalog.enabled?`<div class="payment-configuration"><strong>收款配置待完成</strong><p>${esc(catalog.reason||'请完成 Stripe 账户配置后启用收款。')}</p></div>`:''}<section class="credit-packs" aria-label="积分套餐">${(catalog?.packs||[]).map(pack=>`<article class="credit-pack"><small>${test?'SANDBOX · 测试套餐':'创作积分'}</small><h2>${esc(pack.name)}</h2><strong class="pack-points">${points(pack.creditPoints)}<span>${test?'测试积分':'积分'}</span></strong><div class="pack-price">${money(pack.amountMinor,pack.currency)}<small>一次性付款</small></div><button class="primary-btn" data-action="payment-buy" data-id="${pack.id}" ${!catalog.enabled||paymentSubmitting?'disabled':''}>${test?'前往测试收银台':'使用 Stripe 购买'}</button></article>`).join('')||`<div class="empty"><p>${paymentLoading?'正在加载套餐…':'当前没有已发布的充值套餐。'}</p></div>`}</section><div class="payment-history-heading"><h2>充值订单</h2>${test?`<small>累计测试入账 ${points(paymentCatalog?.testCreditedPoints)} 积分</small>`:''}</div><section class="payment-orders">${paymentOrders.map(paymentOrderHTML).join('')||'<div class="empty small-empty"><p>还没有充值订单</p></div>'}</section>${paymentCursor?'<button class="secondary-btn" data-action="payments-more">加载更早订单</button>':''}`;
}
async function refreshPayments(){if(!cloudUser||paymentLoading)return;paymentLoading=true;const epoch=cloudEpoch;try{
 const [catalog,history]=await Promise.all([cloudRequest('/admin-api/aigc/payments/catalog'),cloudRequest('/admin-api/aigc/payments/orders?limit=50')]);if(epoch!==cloudEpoch)return;
 const changed=history.orders.some(order=>order.status==='PAID'&&paymentOrders.find(old=>old.id===order.id)?.status!=='PAID');
 for(const order of history.orders){if(['PAID','EXPIRED','FAILED','REVIEW'].includes(order.status)&&order.packId){const key='zaomeng-purchase:'+cloudUser.id+':'+order.environment+':'+order.packId;sessionStorage.removeItem(key);paymentRequestKeys.delete(key);}}
 const ids=new Set(history.orders.map(o=>o.id));paymentOrders=[...history.orders,...(paymentOlderLoaded?paymentOrders.filter(o=>!ids.has(o.id)):[])];if(!paymentOlderLoaded)paymentCursor=history.nextId;paymentCatalog={...catalog,testCreditedPoints:history.testCreditedPoints};
 if(paymentReturnOrder&&!paymentOrders.some(o=>o.id===paymentReturnOrder)){const detail=await cloudRequest('/admin-api/aigc/payments/orders/'+encodeURIComponent(paymentReturnOrder));if(epoch!==cloudEpoch)return;paymentOrders.unshift(detail);}
 if(changed)await refreshTasks(false);if(page==='payments')renderPayments();
 if(!paymentPoll)paymentPoll=setInterval(()=>{if(page==='payments'&&document.visibilityState!=='hidden')refreshPayments().catch(()=>{});},5000);
 }finally{if(epoch===cloudEpoch)paymentLoading=false;}}
const paymentRender=render;render=function(){paymentRender();if(page==='payments'){$('#page-name').textContent='充值与订单';renderPayments();}};
const paymentLoadHook=window.studioAfterLoad;window.studioAfterLoad=()=>{paymentLoadHook?.();if(page==='payments')refreshPayments().catch(cloudFail);};
window.studioCaptureAuthReturn=()=>{const id=paymentReturnOrder,kind=paymentReturnKind;return ()=>{paymentReturnOrder=id;paymentReturnKind=kind;};};
const paymentReset=cloudReset;cloudReset=function(){const user=cloudUser?.id;if(user)for(let i=sessionStorage.length-1;i>=0;i--){const key=sessionStorage.key(i);if(key?.startsWith('zaomeng-purchase:'+user+':'))sessionStorage.removeItem(key);}paymentCatalog=null;paymentOrders=[];paymentCursor=null;paymentOlderLoaded=false;paymentReturnOrder=null;paymentReturnKind='';paymentRequestKeys.clear();clearInterval(paymentPoll);paymentPoll=null;paymentSubmitting=false;paymentLoading=false;paymentReset();};
async function openPayments(){closeModal();navigate('payments');if(cloudUser)await refreshPayments();}
actions['payments-open']=cloudAction(openPayments);actions['payments-refresh']=cloudAction(()=>refreshPayments());
async function checkout(packId,existing){
 if(!cloudRequire()||paymentSubmitting)return;if(!paymentCatalog?.enabled){toast(paymentCatalog?.reason||'Stripe 收款尚未配置');return;}
 const storageKey='zaomeng-purchase:'+cloudUser.id+':'+paymentCatalog.environment+':'+packId;
 let key=existing?.key||paymentRequestKeys.get(storageKey)||sessionStorage.getItem(storageKey)||uid();paymentRequestKeys.set(storageKey,key);sessionStorage.setItem(storageKey,key);
 paymentSubmitting=true;const epoch=cloudEpoch;if(page==='payments')renderPayments();
 try{await cloudFlush();const response=await cloudRequest('/admin-api/aigc/payments/checkout',{method:'POST',body:JSON.stringify({packId,clientRequestId:key})});if(epoch!==cloudEpoch)return;
  if(response.order.status==='PAID'){sessionStorage.removeItem(storageKey);paymentRequestKeys.delete(storageKey);await refreshPayments();return;}
  if(!response.checkoutUrl)throw Error('订单尚无可用收银台，请刷新订单状态');const url=new URL(response.checkoutUrl);if(url.protocol!=='https:'||url.hostname!=='checkout.stripe.com')throw Error('收银台地址校验失败');location.assign(url.href);
 }catch(error){if([400,409].includes(error.code)){sessionStorage.removeItem(storageKey);paymentRequestKeys.delete(storageKey);}cloudFail(error);}
 finally{if(epoch===cloudEpoch){paymentSubmitting=false;if(page==='payments')renderPayments();}}
}
actions['payment-buy']=el=>checkout(el.dataset.id);
actions['payment-resume']=cloudAction(async el=>{if(paymentSubmitting)return;paymentSubmitting=true;const epoch=cloudEpoch;try{const result=await cloudRequest('/admin-api/aigc/payments/orders/'+el.dataset.id+'/resume',{method:'POST'});if(epoch!==cloudEpoch)return;if(result.order.status==='PAID'){await refreshPayments();return;}if(!result.checkoutUrl)throw Error('订单收银台暂不可用');const url=new URL(result.checkoutUrl);if(url.protocol!=='https:'||url.hostname!=='checkout.stripe.com')throw Error('收银台地址校验失败');await cloudFlush();location.assign(url.href);}finally{if(epoch===cloudEpoch){paymentSubmitting=false;if(page==='payments')renderPayments();}}});
actions['payments-more']=cloudAction(async()=>{if(!paymentCursor)return;const data=await cloudRequest('/admin-api/aigc/payments/orders?limit=50&beforeId='+encodeURIComponent(paymentCursor));paymentOrders.push(...data.orders);paymentCursor=data.nextId;paymentOlderLoaded=true;renderPayments();});
const paymentCredits=actions.credits;actions.credits=async el=>{await paymentCredits(el);if(cloudUser&&$('.modal .cloud-quota')&&!$('#stripe-topup-entry'))$('.modal .cloud-quota').insertAdjacentHTML('afterend','<div id="stripe-topup-entry" class="stripe-topup-entry"><button class="primary-btn" data-action="payments-open">Stripe 充值</button><button class="secondary-btn" data-action="payments-open">充值订单</button></div>');};
document.querySelector('nav').insertAdjacentHTML('beforeend',`<button class="nav-item" data-nav="payments">${icon('spark')}充值与订单</button>`);
const paymentNavigate=navigate;navigate=function(next){paymentNavigate(next);if(next==='payments'&&cloudUser)refreshPayments().catch(cloudFail);};
const paymentParams=new URLSearchParams(location.search);if(paymentParams.has('stripe_return')){paymentReturnKind=paymentParams.get('stripe_return')==='success'?'success':'cancel';const id=paymentParams.get('order_id');if(id&&/^[1-9][0-9]{0,18}$/.test(id))paymentReturnOrder=id;paymentParams.delete('stripe_return');paymentParams.delete('order_id');const query=paymentParams.toString();history.replaceState(null,'',location.pathname+(query?'?'+query:'')+'#payments');page='payments';}
if(cloudInitialRoute[0]==='payments')page='payments';render();if(cloudUser&&page==='payments')refreshPayments().catch(cloudFail);
